CREATE TABLE "Workflow" ("id" TEXT NOT NULL PRIMARY KEY, "groupId" TEXT NOT NULL, "planRevision" INTEGER NOT NULL, "state" TEXT NOT NULL);
CREATE TABLE "Node" ("id" TEXT NOT NULL PRIMARY KEY, "workflowId" TEXT NOT NULL, "currentAttemptId" TEXT, "state" TEXT NOT NULL);
CREATE TABLE "Attempt" ("id" TEXT NOT NULL PRIMARY KEY, "groupId" TEXT NOT NULL, "workflowId" TEXT NOT NULL, "nodeId" TEXT NOT NULL, "executionDigest" TEXT NOT NULL, "state" TEXT NOT NULL, "holderInstanceId" TEXT NOT NULL, "recordJson" TEXT, "taskJson" TEXT NOT NULL);
CREATE TABLE "Outbox" ("id" TEXT NOT NULL PRIMARY KEY, "sequence" INTEGER NOT NULL, "groupId" TEXT NOT NULL, "attemptId" TEXT NOT NULL, "kind" TEXT NOT NULL, "epoch" INTEGER NOT NULL, "messageJson" TEXT NOT NULL, "acked" BOOLEAN NOT NULL DEFAULT false, "superseded" BOOLEAN NOT NULL DEFAULT false, "deliveryCount" INTEGER NOT NULL DEFAULT 0);
CREATE TABLE "Receipt" ("id" TEXT NOT NULL PRIMARY KEY, "attemptId" TEXT NOT NULL, "recordJson" TEXT NOT NULL, "committed" BOOLEAN NOT NULL DEFAULT false);
CREATE TABLE "Group" ("id" TEXT NOT NULL PRIMARY KEY, "groupId" TEXT NOT NULL, "revision" INTEGER NOT NULL, "metadataJson" TEXT NOT NULL);
CREATE TABLE "Principal" ("id" TEXT NOT NULL PRIMARY KEY, "groupId" TEXT NOT NULL, "revision" INTEGER NOT NULL, "metadataJson" TEXT NOT NULL);
CREATE TABLE "AppInstance" ("id" TEXT NOT NULL PRIMARY KEY, "groupId" TEXT NOT NULL, "revision" INTEGER NOT NULL, "metadataJson" TEXT NOT NULL);
CREATE TABLE "Device" ("id" TEXT NOT NULL PRIMARY KEY, "groupId" TEXT NOT NULL, "revision" INTEGER NOT NULL, "metadataJson" TEXT NOT NULL);
CREATE TABLE "DeviceInstance" ("id" TEXT NOT NULL PRIMARY KEY, "groupId" TEXT NOT NULL, "revision" INTEGER NOT NULL, "metadataJson" TEXT NOT NULL);
CREATE TABLE "Target" ("id" TEXT NOT NULL PRIMARY KEY, "groupId" TEXT NOT NULL, "revision" INTEGER NOT NULL, "metadataJson" TEXT NOT NULL);
CREATE TABLE "Allotment" ("id" TEXT NOT NULL PRIMARY KEY, "groupId" TEXT NOT NULL, "revision" INTEGER NOT NULL, "metadataJson" TEXT NOT NULL);
CREATE TABLE "Credential" ("id" TEXT NOT NULL PRIMARY KEY, "groupId" TEXT NOT NULL, "revision" INTEGER NOT NULL, "metadataJson" TEXT NOT NULL);
CREATE TABLE "Invite" ("id" TEXT NOT NULL PRIMARY KEY, "groupId" TEXT NOT NULL, "revision" INTEGER NOT NULL, "metadataJson" TEXT NOT NULL);
CREATE TABLE "TraceSpan" ("id" TEXT NOT NULL PRIMARY KEY, "groupId" TEXT NOT NULL, "revision" INTEGER NOT NULL, "metadataJson" TEXT NOT NULL);
CREATE TABLE "CostObservation" ("id" TEXT NOT NULL PRIMARY KEY, "groupId" TEXT NOT NULL, "revision" INTEGER NOT NULL, "metadataJson" TEXT NOT NULL);
CREATE TABLE "CalibrationJob" ("id" TEXT NOT NULL PRIMARY KEY, "groupId" TEXT NOT NULL, "revision" INTEGER NOT NULL, "metadataJson" TEXT NOT NULL);
CREATE TABLE "CapabilityState" ("id" TEXT NOT NULL PRIMARY KEY, "groupId" TEXT NOT NULL, "revision" INTEGER NOT NULL, "metadataJson" TEXT NOT NULL);
CREATE TABLE "DispatchSequence" ("id" TEXT NOT NULL PRIMARY KEY, "value" INTEGER NOT NULL);
